+func TestUsageLineageSelectsRelatedRunsThroughCommand(t *testing.T) {
+	c := factProject(t)
+	root := c["root"].(string)
+	for id, meta := range map[string][2]string{
+		"aaaaaaa1": {`{"slug":"fixture"}`, "100"},
+		"bbbbbbb2": {`{"slug":"fixture","resumed_from":"aaaaaaa1","root_build":"aaaaaaa1"}`, "200"},
+		"ccccccc3": {`{"slug":"fixture","root_build":"aaaaaaa1"}`, "400"},
+		"ddddddd4": {`{"slug":"other"}`, "800"},
+	} {
+		dir := filepath.Join(root, ".kogen/local/runs", id)
+		if e := os.MkdirAll(dir, 0700); e != nil {
+			t.Fatal(e)
+		}
+		os.WriteFile(filepath.Join(dir, "result.json"), []byte(meta[0]), 0600)
+		os.WriteFile(filepath.Join(dir, "log.jsonl"), []byte(`{"event":"request","role":"build","at":"2026-10-21T00:00:00Z","usage":{"input":`+meta[1]+`,"cached":0,"output":10,"reasoning":2}}`+"\n"), 0600)
+	}
+	raw, _ := json.Marshal([]string{"intent", "usage", "bbbbbbb2", "--lineage", "--json", "--project", root})
+	cmd := exec.Command(os.Args[0], "-test.run=^TestLocalReadProcess$")
+	cmd.Env = append(os.Environ(), "KOGEN_LOCAL_ARGS="+string(raw))
+	out, e := cmd.CombinedOutput()
+	if e != nil {
+		t.Fatalf("%v: %s", e, out)
+	}
+	var report object
+	if json.Unmarshal(out, &report) != nil {
+		t.Fatal(string(out))
+	}
+	data := report["data"].(map[string]any)
+	scope := data["scope"].(map[string]any)
+	if scope["run_id"] != "bbbbbbb2" || scope["lineage"] != true {
+		t.Fatal(scope)
+	}
+	if data["totals"].(map[string]any)["known_input"] != float64(700) {
+		t.Fatal(data["totals"])
+	}
+	runs := map[string]bool{}
+	for _, r := range data["requests"].([]any) {
+		runs[r.(map[string]any)["run_id"].(string)] = true
+	}
+	if len(runs) != 3 || !runs["aaaaaaa1"] || !runs["bbbbbbb2"] || !runs["ccccccc3"] || runs["ddddddd4"] {
+		t.Fatal(runs)
+	}
+}

